if(PHP_SAPI!=='cli'||!in_array('--confirmar',$argv,true))exit("Uso: php db/migrar_reglas_planilla.php --confirmar\n");require_once __DIR__.'/../config/conexion.php';if(!$conexion->query("SHOW COLUMNS FROM reglas_descuento LIKE 'naturaleza'")->fetch()){$conexion->exec("ALTER TABLE reglas_descuento ADD COLUMN naturaleza ENUM('DESCUENTO','BONIFICACION') NOT NULL DEFAULT 'DESCUENTO' AFTER nombre");echo "Naturaleza agregada.\n";}$c=$conexion->query("SHOW COLUMNS FROM reglas_descuento LIKE 'evento'")->fetch();if($c&&strpos($c['Type'],"'FIJO'")===false){$conexion->exec("ALTER TABLE reglas_descuento MODIFY evento ENUM('TARDANZA','FALTA','SALIDA_ANTICIPADA','HORA_NO_TRABAJADA','FIJO') NOT NULL");echo "Reglas fijas habilitadas.\n";}
